/* ============================================================ 6. card art */

function glyphStopwatch(cx, cy, c1, c2) {
    const R = 92;
    return [
        `<circle cx="${cx - 90}" cy="${cy}" r="${R}" fill="${C.white}" fill-opacity="0.14" stroke="${C.white}" stroke-width="11"/>`,
        `<rect x="${cx - 106}" y="${cy - R - 44}" width="32" height="26" rx="9" fill="${C.white}"/>`,
        `<rect x="${cx - 98}" y="${cy - R - 22}" width="16" height="20" rx="4" fill="${C.white}"/>`,
        `<path d="M${cx - 158} ${cy - 62} l-26 -26" stroke="${C.white}" stroke-width="11" stroke-linecap="round"/>`,
        `<path d="M${cx - 22} ${cy - 62} l26 -26" stroke="${C.white}" stroke-width="11" stroke-linecap="round"/>`,
        `<path d="M${cx - 90} ${cy} L${cx - 90} ${cy - 56}" stroke="${C.white}" stroke-width="11" stroke-linecap="round"/>`,
        `<path d="M${cx - 90} ${cy} L${cx - 40} ${cy + 26}" stroke="${C.white}" stroke-width="11" stroke-linecap="round"/>`,
        `<circle cx="${cx - 90}" cy="${cy}" r="12" fill="${C.white}"/>`,
        // checklist card
        `<rect x="${cx + 46}" y="${cy + 10}" width="206" height="176" rx="22" fill="${C.white}"/>`,
        ...[0, 1, 2].map((i) => {
            const y = cy + 48 + i * 50;
            return [
                `<rect x="${cx + 70}" y="${r(y - 12)}" width="24" height="24" rx="6" fill="${i === 0 ? c1 : C.line}"/>`,
                i === 0 ? tick(cx + 82, y, 8, C.white, 3) : '',
                `<rect x="${cx + 108}" y="${r(y - 7)}" width="${i === 2 ? 92 : 116}" height="12" rx="6" fill="${C.line}"/>`,
            ]
                .filter(Boolean)
                .join('');
        }),
    ].join('\n  ');
}

function glyphBars(cx, cy, c1) {
    const base = cy + 168;
    const heights = [128, 190, 156, 250, 306];
    const barW = 48;
    const gap = 22;
    const x0 = cx - (5 * barW + 4 * gap) / 2;
    const bars = heights
        .map((h, i) => {
            const x = x0 + i * (barW + gap);
            const strong = i === heights.length - 1;
            return `<rect x="${r(x)}" y="${r(base - h)}" width="${barW}" height="${h}" rx="12" fill="${C.white}" fill-opacity="${strong ? 1 : 0.5}"/>`;
        })
        .join('\n  ');
    return [
        ...heights.map(() => ''),
        `<rect x="${r(x0 - 18)}" y="${r(base)}" width="${r(5 * barW + 4 * gap + 36)}" height="9" rx="4.5" fill="${C.white}" fill-opacity="0.5"/>`,
        bars,
        `<line x1="${r(x0 - 18)}" y1="${r(base - 268)}" x2="${r(x0 + 5 * barW + 4 * gap + 18)}" y2="${r(base - 268)}" stroke="${C.white}" stroke-width="6" stroke-dasharray="20 14" stroke-linecap="round"/>`,
        `<path d="M${r(x0 + 5 * barW + 4 * gap + 18)} ${r(base - 268)} l-26 -14 v28 z" fill="${C.white}"/>`,
    ]
        .filter(Boolean)
        .join('\n  ');
}

function glyphDocument(cx, cy, c1) {
    const w = 286;
    const h = 372;
    const x = cx - w / 2 - 10;
    const y = cy - h / 2 - 4;
    const lines = [0, 1, 2, 3].map((i) => {
        const ly = y + 138 + i * 34;
        const lw = i === 3 ? 140 : 214;
        return `<rect x="${x + 32}" y="${r(ly)}" width="${lw}" height="14" rx="7" fill="${C.line}"/>`;
    });
    return [
        `<rect x="${r(x + 26)}" y="${r(y + 22)}" width="${w}" height="${h}" rx="22" fill="${C.white}" fill-opacity="0.35"/>`,
        `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="22" fill="${C.white}"/>`,
        `<rect x="${x + 32}" y="${y + 34}" width="118" height="18" rx="9" fill="${c1}" fill-opacity="0.55"/>`,
        ...lines,
        `<circle cx="${r(x + w - 34)}" cy="${r(y + h - 34)}" r="54" fill="${c1}"/>`,
        tick(x + w - 34, y + h - 34, 26, C.white, 8),
    ].join('\n  ');
}

function glyphLineChart(cx, cy, c1) {
    const base = cy + 168;
    const pts = [
        [cx - 158, base - 96],
        [cx - 82, base - 142],
        [cx - 6, base - 130],
        [cx + 70, base - 210],
        [cx + 146, base - 282],
        [cx + 196, base - 322],
    ];
    const poly = pts.map((p) => `${r(p[0])} ${r(p[1])}`).join(' L');
    const area = `M${r(pts[0][0])} ${r(base - 8)} L${poly} L${r(pts[pts.length - 1][0])} ${r(base - 8)} Z`;
    const grid = [0, 1, 2, 3]
        .map((i) => {
            const y = base - 70 - i * 82;
            return `<line x1="${r(cx - 180)}" y1="${r(y)}" x2="${r(cx + 210)}" y2="${r(y)}" stroke="${C.white}" stroke-width="4" stroke-opacity="0.16"/>`;
        })
        .join('\n  ');
    const dots = pts
        .map((p, i) => {
            const last = i === pts.length - 1;
            return last
                ? `<circle cx="${r(p[0])}" cy="${r(p[1])}" r="30" fill="${C.white}"/><circle cx="${r(p[0])}" cy="${r(p[1])}" r="14" fill="${c1}"/>`
                : `<circle cx="${r(p[0])}" cy="${r(p[1])}" r="14" fill="${C.white}"/>`;
        })
        .join('\n  ');
    return [
        grid,
        `<path d="${area}" fill="${C.white}" fill-opacity="0.12"/>`,
        `<rect x="${r(cx - 180)}" y="${r(base)}" width="392" height="9" rx="4.5" fill="${C.white}" fill-opacity="0.5"/>`,
        `<path d="M${poly}" fill="none" stroke="${C.white}" stroke-width="11" stroke-linecap="round" stroke-linejoin="round"/>`,
        dots,
    ].join('\n  ');
}

const PROGRAM_CARDS = [
    { file: 'tryout-skd.svg', label: 'TRYOUT SKD', hue: 0, glyph: glyphStopwatch },
    { file: 'analisa-skor.svg', label: 'ANALISA SKOR', hue: 8, glyph: glyphBars },
    { file: 'pembahasan.svg', label: 'PEMBAHASAN', hue: -7, glyph: glyphDocument },
    { file: 'riwayat.svg', label: 'RIWAYAT', hue: 16, glyph: glyphLineChart },
];

function programCardSvg({ label, hue, glyph }) {
    const c1 = rotateHue(C.brand, hue);
    const c2 = rotateHue(C.brandDark, hue);
    const inset = rotateHue(C.brand, hue, -0.16);
    return `<svg xmlns="http://www.w3.org/2000/svg" width="700" height="800" viewBox="0 0 700 800" role="img" aria-label="${esc(label)}">
  <title>${esc(label)}</title>
  <defs>
    <linearGradient id="panelFill" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${c1}"/>
      <stop offset="1" stop-color="${c2}"/>
    </linearGradient>
    <clipPath id="panelClip">
      <rect width="700" height="800" rx="28"/>
    </clipPath>
  </defs>
  <g clip-path="url(#panelClip)">
    <rect width="700" height="800" fill="url(#panelFill)"/>
    ${cloud(560, 168, 620, C.white, 0.07)}
    <circle cx="70" cy="770" r="250" fill="${C.white}" fill-opacity="0.05"/>
    <circle cx="656" cy="700" r="150" fill="${C.white}" fill-opacity="0.05"/>
    ${glyph(350, 372, inset, c1)}
    ${text(label, { x: 350, y: 722, size: 46, weight: 700, ls: 4, fill: C.white, anchor: 'middle' })}
    <rect x="280" y="748" width="140" height="6" rx="3" fill="${C.white}" fill-opacity="0.7"/>
  </g>
</svg>
`;
}

/* ================================================================ raster IO */

function svgAsHtml(svg, width, height, background) {
    const sized = svg
        .replace(/<svg([^>]*?)\swidth="[^"]*"/, `<svg$1 width="${width}"`)
        .replace(/<svg([^>]*?)\sheight="[^"]*"/, `<svg$1 height="${height}"`);
    const bg = background ? `background:${background};` : 'background:transparent;';
    return `<!DOCTYPE html><html><head><meta charset="utf-8"><style>html,body{margin:0;padding:0;${bg}overflow:hidden;}</style></head><body>${sized}</body></html>`;
}

async function shoot(page, html, width, height, opaque) {
    await page.setViewportSize({ width, height });
    await page.setContent(html, { waitUntil: 'load' });
    await page.evaluate(() => new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))));
    return page.screenshot({
        omitBackground: !opaque,
        clip: { x: 0, y: 0, width, height },
    });
}

/** ICONDIR + ICONDIRENTRY + embedded PNG payloads. */
function buildIco(images) {
    const header = Buffer.alloc(6);
    header.writeUInt16LE(0, 0); // reserved
    header.writeUInt16LE(1, 2); // type: icon
    header.writeUInt16LE(images.length, 4);

    const entries = Buffer.alloc(16 * images.length);
    let offset = 6 + 16 * images.length;
    images.forEach((img, i) => {
        const e = i * 16;
        entries.writeUInt8(img.size >= 256 ? 0 : img.size, e + 0);
        entries.writeUInt8(img.size >= 256 ? 0 : img.size, e + 1);
        entries.writeUInt8(0, e + 2); // palette size
        entries.writeUInt8(0, e + 3); // reserved
        entries.writeUInt16LE(1, e + 4); // colour planes
        entries.writeUInt16LE(32, e + 6); // bits per pixel
        entries.writeUInt32LE(img.data.length, e + 8);
        entries.writeUInt32LE(offset, e + 12);
        offset += img.data.length;
    });

    return Buffer.concat([header, entries, ...images.map((i) => i.data)]);
}

/* ====================================================================== run */

const written = [];
function put(relPath, data) {
    const full = path.join(ROOT, relPath);
    mkdirSync(path.dirname(full), { recursive: true });
    writeFileSync(full, data);
    written.push(relPath);
}

async function main() {
    // ---- SVG + the raster renders that come from them
    const favicon = faviconSvg();
    put('public/assets/favicon.svg', favicon);
    put('public/assets/img/app-preview.svg', appPreviewSvg());
    for (const card of PROGRAM_CARDS) {
        put(`public/assets/img/cards/${card.file}`, programCardSvg(card));
    }

    const browser = await chromium.launch({
        executablePath: CHROME,
        args: ['--no-sandbox', '--disable-dev-shm-usage', '--font-render-hinting=none'],
    });
    try {
        const page = await browser.newPage({ viewport: { width: 1200, height: 630 }, deviceScaleFactor: 1 });

        // 2. apple-touch-icon: the favicon design, rendered opaque.
        put(
            'public/assets/apple-touch-icon.png',
            await shoot(page, svgAsHtml(favicon, 180, 180, C.white), 180, 180, true),
        );

        // 3. favicon.ico: three transparent PNG payloads in a real ICO container.
        const icoImages = [];
        for (const size of [16, 32, 48]) {
            icoImages.push({
                size,
                data: await shoot(page, svgAsHtml(favicon, size, size, null), size, size, false),
            });
        }
        put('public/assets/favicon.ico', buildIco(icoImages));

        // 4. og-default.png
        put('public/assets/og-default.png', await shoot(page, ogHtml(), 1200, 630, true));
    } finally {
        await browser.close();
    }

    for (const rel of written) {
        const size = statSync(path.join(ROOT, rel)).size;
        console.log(`${String(size).padStart(8)}  ${rel}`);
    }
    console.log(`\n${written.length} files written.`);
}

